/**
 * 极短静音 MP3（24kHz 单声道，约 0.17s，LAME 编码，无 ID3 头）。
 *
 * 微软接口对"没有可朗读内容"的文本（例如只有省略号、破折号、空白）会返回
 * turn.end 但不带任何音频数据。此时如果直接回空响应体，客户端（例如阅读
 * legado）会因为拿到的是坏文件而把这句记为一次错误，连续 5 次就会暂停朗读。
 * 返回一段合法的静音音频，客户端就会正常播放"静音"，符合文本本意。
 */
const SILENT_MP3_BASE64 =
    ''

const SILENT_MP3: Uint8Array = Uint8Array.from(Buffer.from(SILENT_MP3_BASE64, 'base64'))

/** 每次返回独立的 ArrayBuffer，避免调用方持有共享内存。 */
export function silentMp3Audio(): ArrayBuffer {
    return SILENT_MP3.slice().buffer
}

/** 文本里是否含可朗读内容（字母或数字）。纯标点/空白/符号会被判定为不可朗读。 */
export function hasSpeakableText(text: string): boolean {
    return /[\p{L}\p{N}]/u.test(text)
}
